export type ExecutionFindingState='Established as specified'|'Established with non-material deviations'|'Partial / in progress'|'Not executed'|'Not established'|'Materially deviated'|'Stale/conflicting execution evidence';
export type GoalFindingState='Met'|'Not met'|'Mixed'|'Insufficient outcome evidence'|'Not evaluable due to execution deviation'|'Stale/conflicting outcome evidence'|`Not evaluable — ${string}`;
export type ProtectionFindingState='Maintained'|'Protection breach'|'Insufficient protection observations'|'Stale/conflicting protection evidence';
export interface Source{id:string;type:string;responsible:string;evidenceRefs:string[];isSynthetic?:boolean}
export interface InterventionExecutionRecord{id:string;version:number;decisionId:string;approvedVersion:number;interventionId:string;scopeDigest:string;contractDigest:string;actualStart:string|null;actualEnd:string|null;executedScope:unknown;reportedState:'Completed'|'Partial'|'In progress'|'Not executed'|'Unable to establish';deviations:unknown[];source:Source;verification:unknown;availableAt:string;receivedAt:string;recordedAt:string;correction?:unknown}
export interface OutcomeObservation{id:string;version:number;decisionId:string;approvedVersion:number;interventionId:string;contractDigest:string;metric:string;value:number|boolean|string|null;unit:string;baseline:unknown;cohort:string;function:string;window:{start:string;end:string};source:Source;availableAt:string;receivedAt:string;recordedAt:string;coverage:{observed:number;expected:number;definition:string};qualification:unknown;missingReason?:string;missingness:unknown[];context:unknown[];executionDeviations:unknown[];referenceFrame:'original-investigation'|'post-intervention';correction?:unknown}
export interface ExecutionFinding{state:ExecutionFindingState;recordRefs:string[];attributionAllowed:boolean;reason:string}
export interface GoalFinding{state:GoalFindingState;interventionBenefit:string;evidencePurpose:string;criteria:unknown[]}
export interface ProtectionFinding{state:ProtectionFindingState;criteria:unknown[];offsetByBenefit:false;executionCommandIssued:false}
export interface DiagnosisFinding{state:string;inference:string;cannotEstablish:string;sourceRefs:string[]}
export interface OutcomeReview{id:string;version:number;createdAt:string;asOf:string;ruleVersion:string;inputDigest:string;bindingDigest:string;manifest:unknown;executionFinding:ExecutionFinding;goalFinding:GoalFinding;protectionFinding:ProtectionFinding;diagnosisFinding:DiagnosisFinding}
export interface OutcomeEvidenceConversion{id:string;reviewId:string;state:string;mapping:null|{section:'operations';value:unknown;referenceFrame:'original-investigation';supersedesSourceId:string|null};sourceRefs:string[];fingerprint?:string;confirmationHistory:unknown[];committed:boolean;protectionBooleanProjection:false}
